const AR_ASSISTANT_CONFIG = { whatsappNumber: "9779746955071", whatsappMessage: "Hello AR Clothing Zone, I need help with your products.", welcomeMessage: "Welcome to AR Clothing AI. Tell me your vibe and I can suggest anime hoodies, oversized fits, delivery options, sizing, or custom design ideas." }; const assistantResponses = [ { keywords: ["ship", "shipping", "delivery", "deliver", "kathmandu"], response: "Kathmandu delivery usually takes 2 to 3 days after stock and size confirmation. Share your location on WhatsApp for the fastest delivery estimate." }, { keywords: ["anime", "hoodie", "hoodies", "naruto", "graphic", "collection"], response: "For anime style, try the Street Hoodie for a bold main-piece look or Anime Graphic Fit for a cleaner premium outfit. Pair with dark denim or relaxed cargos for a Kathmandu streetwear fit." }, { keywords: ["oversized", "size", "sizing", "fit", "measurement", "measurements", "tee", "tees"], response: "Oversized fits are meant to sit relaxed through the shoulder and body. Choose your usual size for a clean relaxed look, or one size up for a baggier anime streetwear silhouette." }, { keywords: ["order", "buy", "purchase", "payment", "whatsapp"], response: "To order, tap the WhatsApp button and send the product name, size, and delivery location. The team will confirm stock, price, and delivery details before finalizing." }, { keywords: ["track", "tracking", "status"], response: "For order tracking, message us on WhatsApp with your name, phone number, and ordered item. We will check the latest status for you." }, { keywords: ["custom", "print", "design", "personalized"], response: "For custom designs, send your reference image, preferred color, size, and placement idea on WhatsApp. We can guide you on what works best for hoodie or t-shirt prints." }, { keywords: ["style", "styling", "vibe", "outfit", "recommend"], response: "For a strong streetwear outfit, build around one graphic piece: anime hoodie, oversized tee, or custom print. Keep the bottoms simple, then add sneakers or a cap to make the graphic stand out." } ]; const icons = { ai: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2a1 1 0 0 1 1 1v1.08a7.01 7.01 0 0 1 5.92 5.92H20a1 1 0 1 1 0 2h-1.08A7.01 7.01 0 0 1 13 17.92V19h2a3 3 0 0 1 3 3h-2a1 1 0 0 0-1-1H9a1 1 0 0 0-1 1H6a3 3 0 0 1 3-3h2v-1.08A7.01 7.01 0 0 1 5.08 12H4a1 1 0 1 1 0-2h1.08A7.01 7.01 0 0 1 11 4.08V3a1 1 0 0 1 1-1Zm0 4a5 5 0 1 0 0 10 5 5 0 0 0 0-10Zm-2 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm6 0a1 1 0 1 1-2 0 1 1 0 0 1 2 0Zm-6.2 3.2a1 1 0 0 1 1.4 0 1.13 1.13 0 0 0 1.6 0 1 1 0 1 1 1.4 1.43 3.13 3.13 0 0 1-4.4 0 1 1 0 0 1 0-1.43Z"/></svg>', whatsapp: '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12.04 2a9.86 9.86 0 0 0-8.5 14.86L2.4 22l5.28-1.1A9.86 9.86 0 1 0 12.04 2Zm0 1.9a7.96 7.96 0 0 1 6.67 12.3 7.94 7.94 0 0 1-9.95 2.75l-.34-.17-3.55.74.76-3.42-.2-.36A7.96 7.96 0 0 1 12.04 3.9Zm-3.1 3.76c-.17 0-.44.06-.67.32-.23.25-.88.86-.88 2.1 0 1.24.9 2.44 1.03 2.6.13.17 1.75 2.8 4.32 3.82 2.14.84 2.58.67 3.04.63.46-.04 1.5-.61 1.71-1.2.21-.6.21-1.1.15-1.21-.06-.11-.23-.18-.48-.3-.25-.13-1.5-.74-1.73-.82-.23-.08-.4-.13-.57.12-.17.25-.65.82-.8.99-.15.17-.3.19-.55.06-.25-.12-1.07-.39-2.03-1.25-.75-.67-1.26-1.5-1.4-1.75-.15-.25-.02-.39.11-.52.12-.12.25-.3.38-.44.13-.15.17-.25.25-.42.08-.17.04-.32-.02-.45-.06-.13-.57-1.37-.78-1.88-.2-.49-.41-.42-.57-.43h-.49Z"/></svg>' }; function getAssistantResponse(message) { const normalized = message.toLowerCase(); const match = assistantResponses.find((item) => item.keywords.some((keyword) => normalized.includes(keyword))); if (match) return match.response; return "I can help with products, anime hoodie recommendations, oversized sizing, delivery in Kathmandu, and order support. For live stock confirmation, WhatsApp is the fastest option."; } function createMessage(text, type) { const message = document.createElement("div"); message.className = `assistant-message ${type}`; message.textContent = text; return message; } function createTypingBubble() { const bubble = document.createElement("div"); bubble.className = "assistant-message bot"; bubble.innerHTML = '<span class="assistant-typing" aria-label="Assistant is typing"><span></span><span></span><span></span></span>'; return bubble; } function playSoftTick(enabled) { if (!enabled || !window.AudioContext) return; const context = new AudioContext(); const oscillator = context.createOscillator(); const gain = context.createGain(); oscillator.type = "sine"; oscillator.frequency.value = 560; gain.gain.value = 0.025; oscillator.connect(gain); gain.connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + 0.08); } function initAssistantWidget() { if (document.querySelector(".support-widget")) return; let soundEnabled = false; let hasWelcomed = false; const whatsappHref = `https://wa.me/${AR_ASSISTANT_CONFIG.whatsappNumber}?text=${encodeURIComponent(AR_ASSISTANT_CONFIG.whatsappMessage)}`; const widget = document.createElement("div"); widget.className = "support-widget"; widget.innerHTML = ` <button class="support-action support-ai-button" type="button" aria-label="Open AR Clothing AI Assistant" aria-expanded="false"> ${icons.ai} <span class="support-tooltip">Need Styling Help?</span> </button> <a class="support-action support-whatsapp-button" href="${whatsappHref}" target="_blank" rel="noopener noreferrer" aria-label="Chat with AR Clothing Zone on WhatsApp"> ${icons.whatsapp} <span class="support-tooltip">WhatsApp</span> </a> `; const chat = document.createElement("section"); chat.className = "assistant-chat"; chat.setAttribute("aria-label", "AR Clothing AI chat"); chat.setAttribute("aria-hidden", "true"); chat.innerHTML = ` <header class="assistant-chat-header"> <div class="assistant-avatar">${icons.ai}</div> <div> <h2 class="assistant-title">AR Clothing AI</h2> <p class="assistant-subtitle">Ask about anime hoodies, oversized fits, delivery, collections, sizing, or custom designs.</p> </div> <button class="assistant-icon-button assistant-sound" type="button" aria-label="Turn assistant sound on" aria-pressed="false">S</button> <button class="assistant-icon-button assistant-close" type="button" aria-label="Minimize AI assistant">-</button> </header> <div class="assistant-messages" role="log" aria-live="polite" aria-relevant="additions"></div> <div class="assistant-suggestions" aria-label="Quick replies"> <button class="assistant-chip" type="button">Anime Hoodies</button> <button class="assistant-chip" type="button">Oversized Tees</button> <button class="assistant-chip" type="button">Track Order</button> <button class="assistant-chip" type="button">Kathmandu Delivery</button> <button class="assistant-chip" type="button">Custom Design</button> </div> <form class="assistant-form"> <input class="assistant-input" type="text" name="message" autocomplete="off" placeholder="Type your question..." aria-label="Message AR Clothing AI Assistant"> <button class="assistant-send" type="submit" aria-label="Send message">Send</button> </form> `; document.body.append(widget, chat); const aiButton = widget.querySelector(".support-ai-button"); const closeButton = chat.querySelector(".assistant-close"); const soundButton = chat.querySelector(".assistant-sound"); const messages = chat.querySelector(".assistant-messages"); const form = chat.querySelector(".assistant-form"); const input = chat.querySelector(".assistant-input"); const scrollMessages = () => { messages.scrollTop = messages.scrollHeight; }; const addBotMessage = (text) => { const typing = createTypingBubble(); messages.append(typing); scrollMessages(); window.setTimeout(() => { typing.replaceWith(createMessage(text, "bot")); playSoftTick(soundEnabled); scrollMessages(); }, 520); }; const openChat = () => { chat.classList.add("is-open"); chat.setAttribute("aria-hidden", "false"); aiButton.setAttribute("aria-expanded", "true"); if (!hasWelcomed) { hasWelcomed = true; addBotMessage(AR_ASSISTANT_CONFIG.welcomeMessage); } window.setTimeout(() => input.focus({ preventScroll: true }), 120); }; const closeChat = () => { chat.classList.remove("is-open"); chat.setAttribute("aria-hidden", "true"); aiButton.setAttribute("aria-expanded", "false"); aiButton.focus({ preventScroll: true }); }; const submitMessage = (text) => { const cleanText = text.trim(); if (!cleanText) return; messages.append(createMessage(cleanText, "user")); input.value = ""; scrollMessages(); addBotMessage(getAssistantResponse(cleanText)); }; aiButton.addEventListener("click", () => { if (chat.classList.contains("is-open")) { closeChat(); } else { openChat(); } }); closeButton.addEventListener("click", closeChat); soundButton.addEventListener("click", () => { soundEnabled = !soundEnabled; soundButton.setAttribute("aria-pressed", String(soundEnabled)); soundButton.setAttribute("aria-label", soundEnabled ? "Turn assistant sound off" : "Turn assistant sound on"); soundButton.textContent = soundEnabled ? "On" : "S"; playSoftTick(soundEnabled); }); chat.querySelectorAll(".assistant-chip").forEach((chip) => { chip.addEventListener("click", () => submitMessage(chip.textContent)); }); form.addEventListener("submit", (event) => { event.preventDefault(); submitMessage(input.value); }); document.addEventListener("keydown", (event) => { if (event.key === "Escape" && chat.classList.contains("is-open")) { closeChat(); } }); } if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", initAssistantWidget, { once: true }); } else { initAssistantWidget(); }